def extract_even(data):
    def filter_even(item):
        if isinstance(item, int):  # Base case: if it's an integer
            return item if item % 2 == 0 else None  # Keep even numbers
        elif isinstance(item, tuple):  # Recursive case: if it's a tuple
            # Process each element recursively and construct a new tuple
            return tuple(filter_even(sub_item) for sub_item in item if filter_even(sub_item) is not None)
        else:
            # Ignore other types (not required by the problem)
            return None

    return filter_even(data)
